window.products.push({"id":538301,"name":"Electric Wine Opener, Brenari New Automatic Wine Opener With Foil Cutter","category":"homeandappliances","retail price":35.98,"sale price":null,"image":"https://m.media-amazon.com/images/I/81R4ctagAaL._AC_SL1500_.jpg","description":"\"BRENARI ELECTRIC WINE OPENER\" A kitchen tool created to make your wonderful moments even more fun. This unique wine accessory has an ergonomic design that will fit perfectly in your hand and it works flawlessly everytime you push the button. - FOUR STEPS TO OPEN THE WINE BOTTLE 1. Insert the foil cutter to the bottleneck and spin it while holding onto the bottle 2. Put the electric wine opener over the bottleneck and the corkcrew will insert itself into the center of the cork 3. Press onto the lower button until the cork is removed from the bottle 4. Hold the upper button to detach the cork from the electric wine opener 5. Enjoy - SPECIFICATION 1. Battery capacity : 2,800mAh 2. Voltage rating : 6V 3. Power rating : 5W 4. Noise : <75DB","images":["https://m.media-amazon.com/images/I/81R4ctagAaL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Brenari","source_asin":"B0794M8PBP","category_path":"Home & Kitchen"},"sku":"BM-538301","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0794M8PBP","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0794M8PBP","price_pending":true,"merchant_ready":false});
